package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;

/** One holder of a claim: the person holding a share of its due, the share (two decimals) and the sheet's today when shared. */
public record ClaimShare(long personId, BigDecimal share, LocalDate sharedOn) {

    /** The holder's part of a due: the due times the share over 100, rounded half to even. */
    public BigDecimal partOf(BigDecimal due) {
        return due.multiply(share).divide(BigDecimal.valueOf(100), 2, RoundingMode.HALF_EVEN);
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Shares a claim with another person on the sheet: not its own person, not one already holding a share, the shares
 *  totalling at most 100.00; a SETTLED, VOID or DELETED claim cannot be shared. */
public class ApplyShare {
    public void apply(@Val ShareRequest request, @Val Claim claim, Claims claims, People people, Out<Person> holderOut)
            throws ClaimStatusRefusedException {
        ClaimStatus status = claim.getStatus();
        if (status == ClaimStatus.SETTLED || status == ClaimStatus.VOID || status == ClaimStatus.DELETED) {
            throw new ClaimStatusRefusedException("A " + status + " claim cannot be shared");
        }
        Person holder = people.find(claim.getSheetId(), Long.parseLong(request.personId()));
        if (holder == null) {
            throw new ClaimStatusRefusedException("No such person on the sheet");
        }
        if (holder.getId() == claim.getPersonId()) {
            throw new ClaimStatusRefusedException("A claim cannot be shared with its own person");
        }
        BigDecimal total = new BigDecimal(request.share());
        for (ClaimShare held : claims.shares(claim)) {
            if (held.personId() == holder.getId()) {
                throw new ClaimStatusRefusedException(holder.getName() + " already holds a share of the claim");
            }
            total = total.add(held.share());
        }
        if (total.compareTo(BigDecimal.valueOf(100)) > 0) {
            throw new ClaimStatusRefusedException("The claim's shares would total more than 100.00");
        }
        holderOut.set(holder);
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.function.Function;

/**
 * How a claim's live figures (the rate step and the late charge) are rounded: by the sheet's rounding mode in force on the
 * claim's date when one is; else a claim dated before the sheet's policy date rounds half up, one dated on or after it half
 * to even. A correction rounds by the date of the claim it corrects, not its own.
 */
public final class Rounding {

    /** The rounding mode setting's values, as typed. */
    public static final String HALF_UP = "half-up", HALF_EVEN = "half-even";

    private Rounding() {
    }

    /** A rounding mode as stored in a dated setting (1: half up, 2: half to even); null for none. */
    public static BigDecimal code(String mode) {
        return HALF_UP.equals(mode) ? BigDecimal.ONE : HALF_EVEN.equals(mode) ? BigDecimal.valueOf(2) : null;
    }

    /** A stored rounding mode's name ("" for none). */
    public static String name(BigDecimal code) {
        return code == null ? "" : code.intValue() == 1 ? HALF_UP : HALF_EVEN;
    }

    /** A stored rounding mode; null for none. */
    public static RoundingMode mode(BigDecimal code) {
        return code == null ? null : code.intValue() == 1 ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
    }

    /** @param modeOn the sheet's rounding mode in force on a date; null for none. */
    public static RoundingMode of(Claim claim, LocalDate policyDate, Function<LocalDate, RoundingMode> modeOn) {
        RoundingMode set = modeOn.apply(claim.getRoundingDate());
        if (set != null) {
            return set;
        }
        return claim.getRoundingDate().isBefore(policyDate) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
    }
}
