/** The sheet's ancestors as they stood at the end of the date: its parent as last set by then (none when never set by
 *  then), that sheet's parent as last set by then, and so on, up to {@link Rates#ANCESTOR_LEVELS} levels up; then a clone's
 *  source and its own ancestors, in turn (see {@link Rates#chain}). A parent set before its history was kept counts as
 *  of any date. */
public List<String> ancestors(String sheetId, LocalDate date) {
    return Rates.chain(sheetId, at -> parentOn(at, date), sheets::source);
}

private String parentOn(String sheetId, LocalDate date) {
    List<String> set = jdbc.query("SELECT setting_value FROM plain_setting_history WHERE sheet_id = ? AND setting_key = ?"
            + UP_TO + " ORDER BY seq", (rs, i) -> rs.getString(1), sheetId, Settings.PARENT, Date.valueOf(date));
    if (!set.isEmpty()) {
        String last = set.get(set.size() - 1);
        return last.isBlank() ? null : last;
    }
    Integer recorded = jdbc.queryForObject("SELECT COUNT(*) FROM plain_setting_history WHERE sheet_id = ? AND setting_key = ?",
            Integer.class, sheetId, Settings.PARENT);
    return recorded != null && recorded > 0 ? null : sheets.parent(sheetId);
}

/** The periods added by the end of the date, by from-date, each closed (or soft-closed) as it stood then. */
public List<PeriodResponse> periods(String sheetId, LocalDate date) {
    Date end = Date.valueOf(date);
    Map<String, Date> addedOn = new HashMap<>();
    jdbc.query("SELECT name, added_on FROM period WHERE sheet_id = ?", (RowCallbackHandler) rs -> addedOn.put(
            rs.getString(1), rs.getDate(2)), sheetId);
    Map<String, PeriodResponse> byName = new LinkedHashMap<>();
    for (PeriodResponse now : periods.list(sheetId)) {
        Date added = addedOn.get(now.name());
        if (added != null && added.toLocalDate().isAfter(date)) continue;
        byName.put(now.name(), new PeriodResponse(now.name(), now.from(), now.to(), false, "", new LinkedHashMap<>(), false, now.cap(),
                new LinkedHashMap<>(), now.locked(), now.addedOrder()));
    }
    jdbc.query("SELECT name, closed, soft_closed, closed_total, person_totals, person_carried FROM period_history WHERE sheet_id = ?"
            + UP_TO + " ORDER BY seq", (RowCallbackHandler) rs -> {
                PeriodResponse was = byName.get(rs.getString(1));
                if (was == null) return;
                BigDecimal total = rs.getBigDecimal(4);
                byName.put(was.name(), new PeriodResponse(was.name(), was.from(), was.to(), rs.getBoolean(2),
                        total == null ? "" : total.setScale(2).toPlainString(), byPerson(rs.getString(5)), rs.getBoolean(3),
                        was.cap(), byPerson(rs.getString(6)), was.locked(), was.addedOrder()));
            }, sheetId, end);
    return new ArrayList<>(byName.values());
}

