CREATE TABLE plain_setting_history (
    seq           BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id      VARCHAR(200)  NOT NULL,
    set_on        DATE,
    setting_key   VARCHAR(400)  NOT NULL,
    setting_value VARCHAR(400)  NOT NULL
);

